package com.bank.health;

import java.util.logging.Logger;

// Checks whether the account index tree is height-balanced.
public class BalanceCheckService {

    private static final Logger log = Logger.getLogger(BalanceCheckService.class.getName());

    private static final int UNBALANCED = -1; // sentinel

    public boolean isBalanced(IndexNode root) {
        return height(root) != UNBALANCED;
    }

    // Returns subtree height, or UNBALANCED (-1) on first violation.
    private int height(IndexNode node) {
        if (node == null) {
            return 0;
        }
        int left = height(node.getLeft());
        if (left == UNBALANCED) return UNBALANCED;   // short-circuit

        int right = height(node.getRight());
        if (right == UNBALANCED) return UNBALANCED;  // short-circuit

        if (Math.abs(left - right) > 1) {
            return UNBALANCED;                        // imbalance here
        }
        return 1 + Math.max(left, right);
    }

    public boolean checkIndexHealth(IndexNode root) {
        boolean balanced = isBalanced(root);
        if (balanced) {
            log.info("Account index is BALANCED — lookups remain fast");
        } else {
            log.warning("Account index is UNBALANCED — consider rebalancing");
        }
        return balanced;
    }
}
