package com.bank.health;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class BalancedDemo {

    private static final Logger log = Logger.getLogger(BalancedDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Account Index Balance Health");
        BalanceCheckService service = new BalanceCheckService();

        // Balanced:        5000
        //                 /     \
        //              3000     8000
        //              /
        //           1000
        IndexNode balanced = new IndexNode(5000);
        balanced.setLeft(new IndexNode(3000));
        balanced.setRight(new IndexNode(8000));
        balanced.getLeft().setLeft(new IndexNode(1000));
        service.checkIndexHealth(balanced);

        // Unbalanced (left chain depth 3, right depth 0):
        //      5000
        //      /
        //   3000
        //   /
        // 1000
        // /
        // 500
        IndexNode unbalanced = new IndexNode(5000);
        unbalanced.setLeft(new IndexNode(3000));
        unbalanced.getLeft().setLeft(new IndexNode(1000));
        unbalanced.getLeft().getLeft().setLeft(new IndexNode(500));
        service.checkIndexHealth(unbalanced);
    }
}
